def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    g, x1, y1 = extended_gcd(b, a % b)
    return g, y1, x1 - (a // b) * y1

print(gcd(1071, 462))                                    # 21
g, x, y = extended_gcd(240, 46)
print(g, x, y, 240 * x + 46 * y)                          # 2 and coefficients that reconstruct it

