def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    return [p for p, prime in enumerate(is_prime) if prime]

primes = sieve(100)
print(primes)
print(len(primes), "primes below 100")

def boyer_moore_horspool(text, pattern):
    m = len(pattern)
    last = {ch: i for i, ch in enumerate(pattern[:-1])}          # last occurrence of each char, excluding the final one
    matches, i = [], 0
    while i <= len(text) - m:
        j = m - 1
        while j >= 0 and text[i + j] == pattern[j]:
            j -= 1
        if j < 0:
            matches.append(i)
            i += 1
        else:
            i += m - 1 - last.get(text[i + m - 1], -1)           # jump using the character that caused the mismatch
    return matches

print(boyer_moore_horspool("the quick brown fox jumps over the lazy dog", "the"))
print(boyer_moore_horspool("aaaaaaaaaaaaaaaaaaaab", "aaab"))     # worst case: no skipping helps here

def suffix_array(s):
    return sorted(range(len(s)), key=lambda i: s[i:])

def search(s, sa, pattern):
    lo, hi = 0, len(sa)
    while lo < hi:                                    # binary search for the first suffix >= pattern
        mid = (lo + hi) // 2
        if s[sa[mid]:sa[mid] + len(pattern)] < pattern:
            lo = mid + 1
        else:
            hi = mid
    hits = []
    while lo < len(sa) and s[sa[lo]:sa[lo] + len(pattern)] == pattern:
        hits.append(sa[lo]); lo += 1
    return sorted(hits)

text = "banana"
sa = suffix_array(text)
print(sa, [text[i:] for i in sa])                     # positions, sorted by the suffix they start
print(search(text, sa, "ana"))                        # both occurrences of "ana"

import random

random.seed(94)
def exact_distinct(stream):
    return len(set(stream))

def misra_gries(stream, k):                          # frequent items using only k counters
    counters = {}
    for x in stream:
        if x in counters:
            counters[x] += 1
        elif len(counters) < k - 1:
            counters[x] = 1
        else:
            for key in list(counters):
                counters[key] -= 1
                if counters[key] == 0:
                    del counters[key]
    return counters

stream = [random.choice("AAAAABBBBCCDE") for _ in range(10_000)]
print("exact distinct values:", exact_distinct(stream))
print("candidates using only 4 counters:", misra_gries(stream, 5))

import hashlib, random
from collections import Counter

def count_min(stream, width=200, depth=4):
    table = [[0] * width for _ in range(depth)]
    def hashes(item):
        return [int(hashlib.md5(f"{seed}:{item}".encode()).hexdigest(), 16) % width for seed in range(depth)]
    for item in stream:
        for row, col in enumerate(hashes(item)):
            table[row][col] += 1
    def estimate(item):
        return min(table[row][col] for row, col in enumerate(hashes(item)))
    return estimate

random.seed(96)
stream = (["popular"] * 5000) + [f"rare-{i}" for i in range(50_000)]
random.shuffle(stream)
truth = Counter(stream)
estimate = count_min(stream)
print("true count:", truth["popular"], " estimated:", estimate("popular"))
print("a rare item, true count:", truth["rare-1"], " estimated:", estimate("rare-1"), "(never lower than the truth)")

import random

def reservoir_sample(stream, k):
    sample = []
    for n, item in enumerate(stream, start=1):
        if n <= k:
            sample.append(item)
        else:
            j = random.randrange(n)               # a random index from 0 to n-1
            if j < k:
                sample[j] = item
    return sample

random.seed(97)
appearances = [0] * 100
trials = 20_000
for _ in range(trials):
    for item in reservoir_sample(range(100), 5):            # how often does each value make it into the sample at all?
        appearances[item] += 1
expected = trials * 5 / 100                                  # every item should appear about k/n of the time: 5%
print("min", min(appearances), "max", max(appearances), "expected around", round(expected), "each: roughly uniform")

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 2:
        return points
    def half(seq):
        hull = []
        for p in seq:
            while len(hull) >= 2 and cross(hull[-2], hull[-1], p) <= 0:
                hull.pop()
            hull.append(p)
        return hull
    lower = half(points)
    upper = half(reversed(points))
    return lower[:-1] + upper[:-1]

pts = [(0, 0), (2, 0), (2, 2), (0, 2), (1, 1), (3, 1), (1, 3)]
print(convex_hull(pts))                                # the interior point (1,1) is correctly excluded

import math

def closest_pair(points):
    points = sorted(points)
    def rec(pts):                                        # pts sorted by x already
        if len(pts) <= 3:
            return min((math.dist(a, b), a, b) for i, a in enumerate(pts) for b in pts[i + 1:])
        mid = len(pts) // 2
        midx = pts[mid][0]
        best = min(rec(pts[:mid]), rec(pts[mid:]))
        strip = sorted((p for p in pts if abs(p[0] - midx) < best[0]), key=lambda p: p[1])
        for i, a in enumerate(strip):
            for b in strip[i + 1:i + 8]:                  # only a few neighbours in y can possibly be closer
                d = math.dist(a, b)
                if d < best[0]:
                    best = (d, a, b)
        return best
    return rec(points)

pts = [(0, 0), (5, 5), (1, 1), (9, 9), (1.02, 1.01), (7, 2)]
dist, a, b = closest_pair(pts)
print(round(dist, 4), a, b)
